/** Return one UpdateKind from one JSON value. */
export function fromJsonUpdateKind(value: Json): UpdateKind {
    const variant = jsonString(value);

    switch (variant) {
        case "source":
            return "source";
        case "config":
            return "config";
    }

    throw new SerdeError(`unknown enum variant: ${variant}`);
}
